<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('user_management.php');
$page_title='User & Access';$page_subtitle='Administrasi akun dan role teknis. Tidak memberikan akses untuk mengubah isi rekam medis.';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$uid=(int)($_POST['user_id']??0);$active=(int)($_POST['is_active']??0);$role=$_POST['role']??'';$allowed=['admin','doctor','nurse','pharmacist','cashier','patient','registration','medical_record','laboratory','radiology','management','auditor'];
 if($uid===current_user_id()){$msg='Akun Anda sendiri tidak dapat dinonaktifkan atau mengubah role dari halaman ini.';}
 elseif(!in_array($role,$allowed,true)){$msg='Role tidak valid.';}
 else{$s=$pdo->prepare('UPDATE users SET role=?,is_active=? WHERE id=?');$s->execute([$role,$active?1:0,$uid]);audit($pdo,'ADMIN_UPDATE','USER_ACCESS',$uid,'Role/status akun diperbarui oleh administrator.');$msg='Akses akun diperbarui.';}}
$rows=$pdo->query('SELECT id,name,email,role,employee_no,is_active,created_at FROM users ORDER BY role,name')->fetchAll();include __DIR__.'/includes/header.php';?>
<div class="notice"><div>🔐</div><div><strong>Least-privilege administration</strong><span>Administrator mengelola akun dan konfigurasi sistem. Hak akses klinis tetap mengikuti profesi dan ownership; administrator tidak diberi akses untuk mengedit SOAP atau catatan keperawatan.</span></div></div><div style="height:16px"></div>
<?php if($msg):?><div class="alert <?=str_contains($msg,'tidak')||str_contains($msg,'valid')?'danger':'success'?>"><?=h($msg)?></div><?php endif;?>
<div class="card"><div class="card-header"><div><h3 class="section-title">Account Directory</h3><p class="section-subtitle">Aktif/nonaktif dan role setiap akun.</p></div><span class="tag"><?=count($rows)?> akun</span></div><div class="table-wrap"><table><tr><th>User</th><th>Email</th><th>Role</th><th>Employee No</th><th>Status</th><th>Update</th></tr><?php foreach($rows as $r):?><tr><td><b><?=h($r['name'])?></b></td><td><?=h($r['email'])?></td><td><form method="post" style="display:flex;gap:7px;align-items:center"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="user_id" value="<?=$r['id']?>"><select name="role" <?=((int)$r['id']===current_user_id())?'disabled':''?>><?php foreach(['admin','doctor','nurse','pharmacist','cashier','patient','registration','medical_record','laboratory','radiology','management','auditor'] as $rr):?><option value="<?=$rr?>" <?=$r['role']===$rr?'selected':''?>><?=h(role_label($rr))?></option><?php endforeach;?></select></td><td><?=h($r['employee_no']?:'—')?></td><td><span class="badge <?=$r['is_active']?'ok':'danger'?>"><?=$r['is_active']?'ACTIVE':'INACTIVE'?></span></td><td><?php if((int)$r['id']===current_user_id()):?><span class="mini">Current account</span><?php else:?><input type="hidden" name="is_active" value="0"><label style="display:flex;gap:6px;align-items:center"><input type="checkbox" name="is_active" value="1" <?=$r['is_active']?'checked':''?>> aktif</label><button class="btn secondary" style="margin-top:6px">Simpan</button><?php endif;?></form></td></tr><?php endforeach;?></table></div></div>
